}

// Risk tiering keeps governance proportionate, which is what stops teams
// routing around it.
public enum AiRiskTier
{
    Tier3Low,      // internal, no PII, advisory only — standard logging
    Tier2Medium,   // internal, PII, assists decisions — evaluation + named owner
    Tier1High      // customer-facing or automated decisions — full review board
}

