// Client-side token bucket: queue rather than hitting the wall.
public class TokenBucketLimiter(int tokensPerMinute)
{
    private readonly SemaphoreSlim _gate = new(1, 1);
    private double _available = tokensPerMinute;
    private DateTimeOffset _lastRefill = DateTimeOffset.UtcNow;

    public async Task WaitForCapacityAsync(int tokens, CancellationToken ct)
    {
        while (true)
        {
            await _gate.WaitAsync(ct);
            try
            {
                Refill();
                if (_available >= tokens) { _available -= tokens; return; }
            }
            finally { _gate.Release(); }

            // Wait for roughly the shortfall to refill, rather than spinning.
            var shortfall = tokens - _available;
            var wait = TimeSpan.FromSeconds(shortfall / tokensPerMinute * 60);
            await Task.Delay(TimeSpan.FromMilliseconds(Math.Clamp(wait.TotalMilliseconds, 100, 5000)), ct);
        }
    }

    private void Refill()
    {
        var now = DateTimeOffset.UtcNow;
        var elapsed = (now - _lastRefill).TotalSeconds;
        _available = Math.Min(tokensPerMinute, _available + elapsed / 60 * tokensPerMinute);
        _lastRefill = now;
    }
}

// Distribute across regional deployments; weight by granted quota.
public class MultiRegionRouter(IReadOnlyList<RegionalDeployment> deployments)
{
    public RegionalDeployment Select(int estimatedTokens, string? requiredRegion = null)
    {
        var eligible = deployments
            .Where(d => requiredRegion is null || d.Region == requiredRegion)   // residency wins
            .Where(d => d.IsHealthy && d.AvailableTokensPerMinute > estimatedTokens)
            .ToList();

        if (eligible.Count == 0)
            throw new NoCapacityException("No regional deployment has capacity for this request.");

        // Weighted by remaining capacity: spreads load and avoids hammering one region.
        var total = eligible.Sum(d => d.AvailableTokensPerMinute);
        var pick = Random.Shared.NextDouble() * total;
        var running = 0.0;

        foreach (var deployment in eligible)
        {
            running += deployment.AvailableTokensPerMinute;
            if (pick <= running) return deployment;
        }

        return eligible[0];
    }
}

// The ten questions that expose most weak AI architectures.
//
//  1. What happens when the model provider is down for four hours?
//     Weak: "we retry".  Strong: named fallback, evaluated, behaviour difference known.
//
//  2. How does a user get an answer from a document they should not see?
//     Weak: "the prompt says not to".  Strong: filter in the query, negative test in CI.
//
//  3. A document is deleted under a subject access request. What happens?
//     Weak: "we delete the blob".  Strong: blob, index chunks, metadata, audit.
//
//  4. Answer quality drops after a release. How do you find out, and how fast?
//     Weak: "users tell us".  Strong: evaluation gate in CI, groundedness tracked per release.
//
//  5. The monthly bill doubles. What is the first thing you look at?
//     Weak: "the invoice".  Strong: cost per request by feature and tenant, alerted on drift.
//
//  6. An attacker embeds instructions in an uploaded document. What do they gain?
//     Weak: "our filter catches it".  Strong: least privilege means they gain what the user already had.
//
//  7. Why 10 chunks and not 20?
//     Weak: "it felt right".  Strong: measured; 10 scored higher on groundedness AND cost less.
//
//  8. How do you know retrieval is working?
//     Weak: "answers look good".  Strong: recall@k on a fixed evaluation set, tracked over time.
//
//  9. An agent creates a duplicate refund. How?
//     Weak: "it shouldn't".  Strong: it cannot — idempotency key derived from run and step.
//
// 10. What does this cost at 10x volume, and which line dominates?
//     Weak: "ten times more".  Strong: sub-linear here, super-linear there, with the reason.
//
// Strong answers are specific, measured, and name the control. Weak answers are
// assertions. In an interview, the difference is the offer.

